 IEnumerator PhysicalGoal(int sign,bool own){for(int i=0;i<6;i++)m.trucks[i].ResetBody(new Vector3((i<3?-1:1)*5,.36f,-3+(i%3)*3),m.SpawnRotation(i));m.puck.position=new Vector3(sign*(m.goalLine-2),.22f,0);m.puck.linearVelocity=own?Vector3.zero:new Vector3(sign*12,0,0);if(own){m.trucks[0].ResetBody(new Vector3(sign*(m.goalLine-3.7f),.36f,0),Quaternion.Euler(0,sign*90,0));m.trucks[0].body.linearVelocity=new Vector3(sign*7,0,0);}Physics.SyncTransforms();int count=m.rules.Goals;yield return Wait(()=>m.rules.Goals>count,3,"physical goal crossing");}
 IEnumerator Sustained(){m.mode=HockeyMode.AIVsAI;m.Configure();m.durationMinutes=2;for(int i=0;i<6;i++){m.players[i].name=(i<3?"Azure ":"Amber ")+(i%3+1);m.players[i].difficulty=HockeyDifficulty.Hard;}float start=Time.realtimeSinceStartup;int goals=0,recoveries=0;for(int round=0;round<3;round++){Check(m.StartMatch(round>0),"six-AI match/rematch "+round);int oldSign=m.rules.DefendingSign(0);float until=Time.realtimeSinceStartup+600;int lastGoal=-1;while(m.rules.Phase!=HockeyPhase.Finished){if(Time.realtimeSinceStartup>until)throw new Exception("Six-AI match exceeded 10 minutes; phase="+m.rules.Phase+" puck="+m.puck.position+" remaining="+m.rules.Remaining+" goals="+m.rules.Goals);if(m.rules.Goals!=lastGoal){lastGoal=m.rules.Goals;records.Add("MATCH "+round+" goals="+lastGoal+" remaining="+m.rules.Remaining.ToString("F1")+" overtime="+m.rules.Overtime+" faceoffs="+m.EmergencyFaceoffs);File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);}yield return null;}Check(m.rules.Goals>0&&!error,"completed physical six-AI match "+round+" winner="+m.rules.Winner+" goals="+m.rules.Goals+" emergencyFaceoffs="+m.EmergencyFaceoffs+" queryOverflows="+m.QueryOverflows);goals+=m.rules.Goals;recoveries+=m.EmergencyFaceoffs;Capture("six-ai-result-"+round);yield return Delay(.5f);}
 Check(goals>=3,"three full physical matches made scoring progress");for(int i=0;i<6;i++)Check(m.trucks[i].PuckContacts>0&&m.agents[i].Decisions>0,"all six AI physically involved "+i);records.Add("SUSTAINED elapsedSeconds="+(Time.realtimeSinceStartup-start).ToString("F1")+" three complete two-minute regulation matches including overtime / pauses between goals; totalGoals="+goals+" emergencyFaceoffs="+recoveries); }
